// Monta o e-mail de recuperação de senha a partir do que a função
// recuperar-senha do Supabase mandou: { email, nome, link, validadeMinutos }.
const b = $input.first().json.body || {};

const email = String(b.email || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('E-mail inválido: ' + email);

// Só aceita o link oficial de recuperação do Supabase do EasyFeed: ninguém
// consegue usar este workflow para mandar outro link pelo nosso domínio.
const link = String(b.link || '').trim();
if (!link.startsWith('https://lixrcruilisncfhfhndo.supabase.co/auth/v1/verify?')) throw new Error('Link de recuperação inesperado.');

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const primeiroNome = String(b.nome || '').trim().split(/\s+/)[0].slice(0, 40);
const oi = primeiroNome ? 'Oi, ' + primeiroNome + '!' : 'Oi!';
const minutos = Number(b.validadeMinutos) || 60;
const validade = minutos % 60 === 0 ? (minutos / 60 === 1 ? '1 hora' : (minutos / 60) + ' horas') : minutos + ' minutos';

const assunto = 'Crie sua nova senha do EasyFeed';

const html = `<!doctype html>
<html lang="pt-BR">
<body style="margin:0;padding:0;background:#F1F5F9;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F1F5F9;padding:32px 12px;">
    <tr><td align="center">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;background:#FFFFFF;border-radius:14px;border:1px solid #E2E8F0;">
        <tr><td style="padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;">
          <div style="font-size:22px;font-weight:700;color:#2563EB;">EasyFeed</div>
        </td></tr>
        <tr><td style="padding:12px 28px 4px 28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#334155;">
          <p style="margin:0 0 14px 0;font-size:17px;color:#0F172A;font-weight:700;">${esc(oi)}</p>
          <p style="margin:0 0 14px 0;">Recebemos um pedido para trocar a senha da sua conta no EasyFeed. Para criar uma nova, é só clicar no botão:</p>
        </td></tr>
        <tr><td align="center" style="padding:10px 28px 18px 28px;">
          <a href="${esc(link)}" style="display:inline-block;background:#2563EB;color:#FFFFFF;text-decoration:none;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:700;padding:13px 26px;border-radius:10px;">Criar nova senha</a>
        </td></tr>
        <tr><td style="padding:0 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:22px;color:#475569;">
          <p style="margin:0 0 12px 0;">O link vale por ${validade} e só funciona uma vez.</p>
          <p style="margin:0 0 12px 0;">Se não foi você que pediu, pode ignorar este e-mail. Sua senha continua a mesma.</p>
          <p style="margin:0 0 4px 0;">Equipe EasyFeed</p>
        </td></tr>
        <tr><td style="padding:16px 28px 26px 28px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:18px;color:#94A3B8;">
          Se o botão não abrir, copie e cole este endereço no navegador:<br>
          <a href="${esc(link)}" style="color:#2563EB;word-break:break-all;">${esc(link)}</a>
        </td></tr>
      </table>
      <p style="font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#94A3B8;margin:16px 0 0 0;">EasyFeed, um produto da IAMAI · easyfeed.com.br<br>Este e-mail é automático, não precisa responder.</p>
    </td></tr>
  </table>
</body>
</html>`;

const texto = [
  oi,
  '',
  'Recebemos um pedido para trocar a senha da sua conta no EasyFeed. Para criar uma nova, abra este link:',
  link,
  '',
  'O link vale por ' + validade + ' e só funciona uma vez.',
  'Se não foi você que pediu, pode ignorar este e-mail. Sua senha continua a mesma.',
  '',
  'Equipe EasyFeed',
  'EasyFeed, um produto da IAMAI · easyfeed.com.br',
].join('\n');

return [{ json: { para: email, assunto, html, texto } }];
